 async void RequestBackup(string action){if(Browser.CoreWebView2==null||Pending!=null)return;if(!Uri.TryCreate(Browser.Source?.AbsoluteUri,UriKind.Absolute,out var uri)||uri.GetLeftPart(UriPartial.Authority)!=Site)return;Pending=action;Report("جارٍ التحقق من حساب المالك… / Checking owner account…");try{await Browser.CoreWebView2.ExecuteScriptAsync("(async()=>{try{const workspace=await fetch('/api/workspace',{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!workspace.ok)throw Error('Sign in as owner / سجل دخول المالك');const scope=await workspace.json();const headers={'Content-Type':'application/json','X-GymOS-Tenant':scope.owner};const start=await fetch('/api/backup',{method:'POST',headers,body:JSON.stringify({action:'downloadStart'}),signal:AbortSignal.timeout(120000)});if(!start.ok)throw Error('Backup unavailable');const m=await start.json();let data;try{if(m.bytes>67108864||m.bytes<1)throw Error('Backup too large');const bytes=new Uint8Array(m.bytes);for(let i=0;i<m.parts;i++){const r=await fetch('/api/backup?transfer='+encodeURIComponent(m.id)+'&part='+i,{cache:'no-store',headers,signal:AbortSignal.timeout(120000)});if(!r.ok)throw Error('Backup download failed');const chunk=await r.json();const part=Uint8Array.from(atob(chunk.data),c=>c.charCodeAt(0));if(part.length!==Math.min(m.chunkBytes,m.bytes-i*m.chunkBytes))throw Error('Invalid backup chunk');bytes.set(part,i*m.chunkBytes);}const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(b=>b.toString(16).padStart(2,'0')).join('');if(digest!==m.digest)throw Error('Backup integrity failed');data=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}finally{await fetch('/api/backup',{method:'POST',headers,body:JSON.stringify({action:'transferCancel',id:m.id})}).catch(()=>{});}window.chrome.webview.postMessage({type:'gymos-backup',backup:data});}catch(e){window.chrome.webview.postMessage({type:'gymos-backup-error',message:String(e)});}})()");}catch{Pending=null;Repor