 void ReceiveBackup(object? sender,CoreWebView2WebMessageReceivedEventArgs args){if(args.WebMessageAsJson.Length>100000000)return;if(!Uri.TryCreate(args.Source,UriKind.Absolute,out var uri)||uri.GetLeftPart(UriPartial.Authority)!=Site)return;try{using var command=JsonDocument.Parse(args.WebMessageAsJson);var message=command.RootElement;if(message.TryGetProperty("type",out var kind)&&kind.GetString()=="gymos-desktop"){if(!message.TryGetProperty("action",out var requested)||requested.ValueKind!=JsonValueKind.String)return;var name=requested.GetString();if(!DesktopCommands.Allowed(name)||args.WebMessageAsJson.Length>DesktopCommands.MaxPayloadLength(name))return;switch(name){case "trial":if(message.TryGetProperty("mode",out var trialMode)&&trialMode.GetString()=="trial"){try{if(!message.TryGetProperty("serverNow",out var serverStamp)||!serverStamp.TryGetInt64(out var stamp)||Math.Abs((DateTimeOffset.UtcNow-DateTimeOffset.FromUnixTimeMilliseconds(stamp)).TotalMinutes)>5)throw new InvalidOperationException("Check Windows clock");var start=DateTimeOffset.Parse(message.GetProperty("start").GetString()!);var end=DateTimeOffset.Parse(message.GetProperty("end").GetString()!);TrialClock.Activate(start,end,DateTimeOffset.UtcNow);trialActive=true;CheckLocalTrial();}catch{trialActive=false;StopMusic();Speech.Stop();Browser.CoreWebView2.Navigate(Site+"/clubs?trial=local-check");}}else trialActive=false;break;case "musicStop":StopMusic();break;case "music":if(message.TryGetProperty("url",out var musicUrl)&&musicUrl.ValueKind==JsonValueKind.String&&message.TryGetProperty("scope",out var musicScope)&&musicScope.ValueKind==JsonValueKind.String)OpenMusic(musicUrl.GetString()!,musicScope.GetString()!);break;case "branding":if(message.TryGetProperty("clear",out var clearing)&&clearing.ValueKind==JsonValueKind.True)ApplyBrand(null,true);else if(message.TryGetProperty("owner",out var brandOwner)&&message.TryGetProperty("name",out var brandName)&&message.TryGetProperty("logo",out var brandLo